// Treat the pasted text and the image as untrusted DATA, never as instructions.
// Enforce size and type limits before anything reaches an AI provider.
const body = $json.body || {};
const text = String(body.text || '').slice(0, 4000);
const requestId = String(body.requestId || $execution.id);
const image = $input.item.binary && $input.item.binary.image;
const allowed = ['image/png', 'image/jpeg', 'image/webp'];
const hasImage = Boolean(image);
const badImage = hasImage && (!allowed.includes(image.mimeType) || Number(image.fileSize) > 5 * 1024 * 1024);
return { json: { requestId, text, hasImage, badImage }, binary: $input.item.binary };

// Validate any AI output before returning it. Until a provider is connected there is NO
// result, and this template says so instead of pretending it read the screenshot.
//
// This mirrors src/features/import/schemas.ts's validateExtractedSchedule() field-for-field,
// on purpose: the frontend re-validates whatever this returns anyway, but a workflow that
// only ever produces valid shapes is much easier to debug, and it means a badly-behaved AI
// provider response gets caught here instead of silently becoming a UI error later.
const ai = $json.aiResult;
const fallback = (message) => ({
  json: {
    requestId: $json.requestId,
    status: 'error',
    confidence: 0,
    meetings: [],
    constraints: { latestEnd: null, lunchStart: null, needsOpeningShift: false, preference: 'any', daysPerWeek: null },
    warnings: [message],
    unresolved: [],
  },
});
if (!ai) {
  return fallback($json.badImage ? 'That image type or size is not allowed.' : 'This workflow has no AI provider connected yet, so nothing was read.');
}

const DAYS = ['mon', 'tue', 'wed', 'thu', 'fri'];
const isRecord = (v) => typeof v === 'object' && v !== null && !Array.isArray(v);
const inDay = (v) => typeof v === 'number' && Number.isInteger(v) && v >= 0 && v <= 24 * 60;

if (!isRecord(ai)) return fallback('The AI provider response was not an object, so it was ignored.');
if (typeof ai.confidence !== 'number' || ai.confidence < 0 || ai.confidence > 1) {
  return fallback('The AI provider response had an invalid confidence value, so it was ignored.');
}

const meetings = [];
if (Array.isArray(ai.meetings)) {
  for (const m of ai.meetings) {
    if (isRecord(m) && DAYS.includes(m.day) && inDay(m.start) && inDay(m.end) && m.end > m.start) {
      meetings.push({ day: m.day, start: m.start, end: m.end, source: 'class' });
    }
    // Malformed individual meetings are dropped rather than failing the whole response —
    // a partially-read screenshot is still more useful than nothing, and the frontend shows
    // the manager exactly what came back for review before anything is saved.
  }
}

const c = isRecord(ai.constraints) ? ai.constraints : {};
const clampList = (list) => (Array.isArray(list) ? list.slice(0, 20).map((w) => String(w).slice(0, 300)) : []);

return {
  json: {
    requestId: $json.requestId,
    status: ['ok', 'needs_review', 'error'].includes(ai.status) ? ai.status : 'needs_review',
    confidence: ai.confidence,
    meetings,
    constraints: {
      latestEnd: inDay(c.latestEnd) ? c.latestEnd : null,
      lunchStart: inDay(c.lunchStart) ? c.lunchStart : null,
      needsOpeningShift: Boolean(c.needsOpeningShift),
      preference: ['any', 'morning', 'afternoon'].includes(c.preference) ? c.preference : 'any',
      daysPerWeek: typeof c.daysPerWeek === 'number' && Number.isInteger(c.daysPerWeek) && c.daysPerWeek >= 1 && c.daysPerWeek <= 5 ? c.daysPerWeek : null,
    },
    warnings: clampList(ai.warnings),
    unresolved: clampList(ai.unresolved),
  },
};
